                goto case 0x8F97;
            case 0x8F97: // LDX A,X ;GET STATE  (JOUSTRV4.ASM:6241)
                if (!g.I(0x8F97, 6)) return 0x8F97;
                ea = (ushort)(t.X + (sbyte)t.A);
                t.X = g.Rd16(ea); t.CC = Logic16(t.CC, t.X);
                goto case 0x8F99;
            case 0x8F99: // STX PSTATE,U ; & REMEMBER IT  (JOUSTRV4.ASM:6242)
                if (!g.I(0x8F99, 6)) return 0x8F99;
                ea = (ushort)(t.U + 32);
                g.Wr16(ea, t.X); t.CC = Logic16(t.CC, t.X);
                goto case 0x8F9C;
            case 0x8F9C: // CLR PTIMX,U ;ALSO CHANGE ANIMATION FRAME  (JOUSTRV4.ASM:6243)
                if (!g.I(0x8F9C, 7)) return 0x8F9C;
                ea = (ushort)(t.U + 22);
                g.Rd(ea); g.Wr(ea, 0); t.CC = Clr(t.CC);
                goto case 0x8F9F;
            case 0x8F9F: // CLR PACCX,U ;IMMEDIATE LAND JOYSTICK SERVICE  (JOUSTRV4.ASM:6244)
                if (!g.I(0x8F9F, 7)) return 0x8F9F;
                ea = (ushort)(t.U + 21);
                g.Rd(ea); g.Wr(ea, 0); t.CC = Clr(t.CC);
                goto case 0x8FA2;
            case 0x8FA2: // LDA #1 ;MINIMUM DOWN TIME  (JOUSTRV4.ASM:6245)
                if (!g.I(0x8FA2, 2)) return 0x8FA2;
                t.A = 0x01; t.CC = Logic8(t.CC, t.A);
                goto case 0x8FA4;
            case 0x8FA4: // STA PTIMUP,U  (JOUSTRV4.ASM:6246)
                if (!g.I(0x8FA4, 5)) return 0x8FA4;
                ea = (ushort)(t.U + 19);
                g.Wr(ea, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0x8FA7;
            case 0x8FA7: // LDD #0 ;NO PVELY, (FOR INTELLIGENCE)  (JOUSTRV4.ASM:6247)
                if (!g.I(0x8FA7, 3)) return 0x8FA7;
                t.D = 0x0000; t.CC = Logic16(t.CC, t.D);
                goto case 0x8FAA;
            case 0x8FAA: // STD PVELY,U  (JOUSTRV4.ASM:6248)
                if (!g.I(0x8FAA, 6)) return 0x8FAA;
                ea = (ushort)(t.U + 17);
                g.Wr16(ea, t.D); t.CC = Logic16(t.CC, t.D);
                goto case 0x8FAD;
            case 0x8FAD: // LDA #STAND ;LAND STANDING  (JOUSTRV4.ASM:6249)
                if (!g.I(0x8FAD, 2)) return 0x8FAD;
                t.A = 0x0C; t.CC = Logic8(t.CC, t.A);
                goto case 0x8FAF;
            case 0x8FAF: // STA PIMAGE,U  (JOUSTRV4.ASM:6250)
                if (!g.I(0x8FAF, 5)) return 0x8FAF;
                ea = (ushort)(t.U + 23);
                g.Wr(ea, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0x8FB2;
            case 0x8FB2: // JMP PL2EDG ;NO MORE FLYING  (JOUSTRV4.ASM:6251)
                if (!g.I(0x8FB2, 4)) return 0x8FB2;
                return 0x8DEF;
        }
        return pc;
    }

